// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this));
        vm.deal(address(c), amount);
        vm.prank(actor);
        try c.withdrawAll(actor) {
            assertTrue(false);
        } catch {
            assertTrue(address(c).balance == amount);
        }
    }
}
